{
  "summary": "The function fn_14 processes input data and writes a base64-encoded string to the output buffer. It returns the number of bytes written or VERA_ERR if the output buffer is too small.",
  "proposed_name": "Base64 Encoding",
  "algorithm": "Base64",
  "self_confidence": 0.99,
  "claims": [
    {
      "id": "user_1",
      "type": "IO",
      "text": "Returns 0xFFFFFFFFFFFFFFFF when out_cap < (len + 2) / 3 << 2.",
      "asserted_values": ["0xFFFFFFFFFFFFFFFF"],
      "confidence": 1.0,
      "io": {
        "when": "out_cap < (len + 2) / 3 << 2",
        "returns": "0xFFFFFFFFFFFFFFFF"
      }
    },
    {
      "id": "user_2",
      "type": "IO",
      "text": "Returns len when out_cap >= (len + 2) / 3 << 2.",
      "asserted_values": ["len"],
      "confidence": 1.0,
      "io": {
        "when": "out_cap >= (len + 2) / 3 << 2",
        "returns": "len"
      }
    },
    {
      "id": "user_3",
      "type": "SIDE",
      "text": "Writes base64-encoded data to out[0..len].",
      "asserted_values": [],
      "confidence": 1.0,
      "io": {
        "writes_out": true
      }
    },
    {
      "id": "user_4",
      "type": "CF",
      "text": "Processes input in chunks of 3 bytes, then handles remaining bytes (1 or 2).",
      "asserted_values": [],
      "confidence": 1.0
    },
    {
      "id": "user_5",
      "type": "CONST",
      "text": "Uses the constant \"AfhmdLEr3GMxg2S/a91UZnTlHOI5KYzevFCwNQ+P4tWV7cpXRbDuykjJsoi6q80B\" for base64 encoding.",
      "asserted_values": ["\"AfhmdLEr3GMxg2S/a91UZnTlHOI5KYzevFCwNQ+P4tWV7cpXRbDuykjJsoi6q80B\""],
      "confidence": 1.0
    },
    {
      "id": "user_6",
      "type": "ALG",
      "text": "Implements base64 encoding.",
      "asserted_values": ["base64"],
      "confidence": 1.0
    }
  ],
  "recovered_c": "#include <stdint.h>\n#include <stddef.h>\n\nuint64_t fn_14(const uint8_t *in, size_t len, uint64_t arg, uint8_t *out, size_t out_cap) {\n  size_t o = 0;\n  size_t i = 0;\n\n  if (out_cap < (len + 2) / 3 << 2) {\n    return 0xFFFFFFFFFFFFFFFF;\n  }\n\n  const char *base64_table = \"AfhmdLEr3GMxg2S/a91UZnTlHOI5KYzevFCwNQ+P4tWV7cpXRbDuykjJsoi6q80B\";\n\n  for (; i + 3 <= len; i += 3) {\n    uint32_t chunk = (uint32_t)in[i] << 16 | (uint32_t)in[i + 1] << 8 | (uint32_t)in[i + 2];\n    out[o] = base64_table[(chunk >> 18) & 0x3F];\n    out[o + 1] = base64_table[(chunk >> 12) & 0x3F];\n    out[o + 2] = base64_table[(chunk >> 6) & 0x3F];\n    out[o + 3] = base64_table[chunk & 0x3F];\n    o += 4;\n  }\n\n  if (len - i == 1) {\n    uint32_t chunk = (uint32_t)in[i] << 16;\n    out[o] = base64_table[(chunk >> 18) & 0x3F];\n    out[o + 1] = base64_table[(chunk >> 12) & 0x3F];\n    out[o + 2] = base64_table[(chunk >> 6) & 0x3F];\n    out[o + 3] = '=';\n    o += 4;\n  }\n  else if (len - i == 2) {\n    uint32_t chunk = (uint32_t)in[i] << 16 | (uint32_t)in[i + 1] << 8;\n    out[o] = base64_table[(chunk >> 18) & 0x3F];\n    out[o + 1] = base64_table[(chunk >> 12) & 0x3F];\n    out[o + 2] = base64_table[(chunk >> 6) & 0x3F];\n    out[o + 3] = '=';\n    o += 4;\n  }\n\n  return o;\n}"
}
